const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=s=>s==null?'—':`${Math.floor(s/60)}m ${Math.round(s%60)}s`;
let loaded=new Set();
function chart(m){const values=[m.reference?.result?.passed?m.reference.result.estimated_time_seconds:null,...m.attempts.map(a=>a.result.passed?a.result.estimated_time_seconds:null)].filter(x=>x!=null);if(!values.length)return '';let best=Infinity;const incumbent=values.map(v=>best=Math.min(best,v));const max=Math.max(...values),min=Math.min(...values)*.9;const points=incumbent.map((v,i)=>`${20+i*460/Math.max(1,values.length-1)},${60-(v-min)/(max-min||1)*50}`).join(' ');return `<svg class="chart" viewBox="0 0 500 70" aria-label="Best passing time across attempts"><path d="M20 62 H480" stroke="#dae2d4"/><polyline points="${points}" fill="none" stroke="#4c7948" stroke-width="2.5"/>${incumbent.map((v,i)=>`<circle cx="${20+i*460/Math.max(1,values.length-1)}" cy="${60-(v-min)/(max-min||1)*50}" r="3" fill="#4c7948"/>`).join('')}</svg>`;}
async function details(id){const el=document.getElementById('detail-'+id);if(!el||loaded.has(id))return;const m=await fetch('/api/study-run?part='+id).then(r=>r.json());el.innerHTML=chart(m)+m.attempts.map(a=>`<div class="attempt"><b>CAM attempt ${a.index+1} · <span class="${a.result.passed?'':'fail'}">${a.result.passed?'PASS · '+fmt(a.result.estimated_time_seconds):'FAIL'}</span></b><p>${esc(a.proposal?.summary||'')}</p><p>${esc(a.result.issues.slice(0,3).map(i=>i.description).join(' '))}</p>${a.judge?`<p>Timing judge: <b>${esc(a.judge.value.action)}</b> — ${esc(a.judge.value.reason)}</p>`:''}<details><summary>CAM parameters</summary><pre>${esc(JSON.stringify(a.strategy,null,2))}</pre></details></div>`).join('');if(m.status!=='running')loaded.add(id);}
async function refresh(){const d=await fetch('/api/study-results').then(r=>r.json()),complete=d.parts.filter(r=>r.best_seconds!=null),comparable=complete.filter(r=>r.reference_seconds!=null),ref=comparable.reduce((s,r)=>s+r.reference_seconds,0),best=comparable.reduce((s,r)=>s+r.best_seconds,0),audit=d.held_out_audit;
document.querySelector('h1').textContent=`${d.catalog.length} parts. Continuous memory.`;
$('stats').innerHTML=[['Passing parts',`${complete.length} / ${d.catalog.length}`],['Matched references',fmt(ref)],['Matched best plans',fmt(best)],['Matched time reduction',ref?(100*(1-best/ref)).toFixed(1)+'%':'—']].map(([label,value])=>`<div class="stat"><strong>${value}</strong><span>${label}</span></div>`).join('');
$('learning-text').textContent=d.memory?`Memory v${d.memory.version}: ${d.memory.episodes?.length||0} saved run episodes. Each next run reloads the committed file. ${audit.pairs.length?`Later first-proposal comparisons: cold ${audit.cold_valid}/${audit.pairs.length} valid; memory-assisted ${audit.warm_valid}/${audit.pairs.length} valid. Warm was faster on ${audit.warm_faster}, slower on ${audit.warm_slower}, and tied on ${audit.tied} jointly valid pairs.`:'This run does not include a controlled memory-benefit comparison.'} Saved memories are observed history, not a guarantee of better performance.`:'Sequential runs are starting.';
$('audit').innerHTML=audit.pairs.length?`<table><tr><th>Later part</th><th>Cold proposal</th><th>Memory-assisted proposal</th></tr>${audit.pairs.map(p=>`<tr><td>${esc(p.id)}</td><td>${p.cold_passed?fmt(p.cold_seconds):'FAIL'}</td><td>${p.warm_passed?fmt(p.warm_seconds):'FAIL'}</td></tr>`).join('')}</table><p class="notes">${esc(audit.interpretation)}</p>`:'';
for(const p of d.catalog){const r=d.parts.find(r=>r.id===p.id);let card=document.getElementById('card-'+p.id);if(!card){card=document.createElement('article');card.className='card';card.id='card-'+p.id;card.innerHTML=`<div class="media"></div><div class="body"><div class="row"><span class="eyebrow">${esc(p.split.replace('_',' '))}</span><span class="pill state"></span></div><h2>${esc(p.name)}</h2><div class="times"></div><div class="links"></div><details><summary>CAM attempts &amp; timing decisions</summary><div id="detail-${p.id}"></div></details></div>`;$('cards').append(card);card.querySelector('details').addEventListener('toggle',()=>{if(card.querySelector('details').open)details(p.id);});}
card.querySelector('.state').textContent=(r?.status||'queued')+(r?.saved_memory_version?' · memory '+r.loaded_memory_version+' → '+r.saved_memory_version:'');card.querySelector('.state').className='pill state'+(r?.error||r?.status==='failed'?' fail':'');card.querySelector('.times').innerHTML=`<div><strong>${fmt(r?.reference_seconds)}</strong><span>Reference</span></div><div><strong>${fmt(r?.best_seconds)}</strong><span>Best passing</span></div><div><strong>${r?.reduction_percent==null?'—':r.reduction_percent.toFixed(1)+'%'}</strong><span>Time reduction</span></div>`;
const media=card.querySelector('.media');if(r?.video_ready&&!media.querySelector('video'))media.innerHTML=`<video controls preload="none" poster="/study-videos/${p.id}.png" src="/study-videos/${p.id}.mp4"></video>`;else if(!media.children.length)media.innerHTML='<div class="placeholder">Machining replay is being prepared</div>';
card.querySelector('.links').innerHTML=r?.playback_ready?`<a href="housing.html?part=${p.id}&study=${encodeURIComponent(d.asset_namespace||'')}">Interactive machine replay ↗</a><a href="/api/study-run?part=${p.id}">Raw evaluation JSON</a>`:'';
if(card.querySelector('details').open)details(p.id);
}}
$('gate').parentElement.addEventListener('toggle',async()=>{if(!$('gate').parentElement.open)return;const e=await fetch('/api/study-learning').then(r=>r.json());$('gate').innerHTML=e.episodes?e.episodes.map((ep,i)=>`<div class="attempt"><b>Memory ${i+1} · ${esc(ep.part)}</b><p>${ep.passed_attempts} passing attempts; ${ep.failed_attempts} failed attempts. Best ${fmt(ep.best_seconds)}.</p><p>${esc(ep.proposed_note?.guidance||'Observed run results saved.')}</p><p>${esc(ep.note_status||'')}</p></div>`).join(''):'No memories saved yet.';});
$('capture-all').onclick=async()=>{const d=await fetch('/api/study-results').then(r=>r.json());const p=d.parts.find(p=>p.playback_ready&&!p.video_captured);if(p)location.href='housing.html?part='+p.id+'&study='+encodeURIComponent(d.asset_namespace||'')+'&capture=queue';else $('capture-all').textContent=d.parts.every(p=>p.video_captured)?'Videos already captured':'Waiting for first playback';};
refresh().catch(e=>$('learning-text').textContent=e.message);setInterval(()=>refresh().catch(()=>{}),5000);
